CREATE TABLE `payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `invoice_id` bigint unsigned NOT NULL,
  `invoice_item_id` bigint unsigned DEFAULT NULL,
  `payment_method` enum('wallet','mpesa_stk','mpesa_paybill','bank_transfer','cash','manual_topup','message_paste') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'wallet',
  `source` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amount` decimal(12,2) NOT NULL,
  `wallet_balance_before` decimal(12,2) DEFAULT NULL,
  `wallet_balance_after` decimal(12,2) DEFAULT NULL,
  `transaction_reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `external_reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('pending','completed','failed','cancelled','refunded') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'completed',
  `is_reconciled` tinyint(1) NOT NULL DEFAULT '0',
  `reconciled_at` timestamp NULL DEFAULT NULL,
  `reconciled_by` bigint unsigned DEFAULT NULL,
  `meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_payments_tenant_id` (`tenant_id`),
  KEY `idx_payments_user_id` (`user_id`),
  KEY `idx_payments_invoice_id` (`invoice_id`),
  KEY `idx_payments_invoice_item_id` (`invoice_item_id`),
  KEY `idx_payments_status` (`status`),
  KEY `idx_payments_payment_method` (`payment_method`),
  KEY `idx_payments_created_at` (`created_at`),
  KEY `idx_payments_tenant_status` (`tenant_id`,`status`),
  KEY `idx_payments_date_status` (`created_at`,`status`),
  KEY `idx_payments_reconciled` (`is_reconciled`),
  KEY `idx_payments_transaction_reference` (`transaction_reference`),
  KEY `fk_payments_reconciled_by` (`reconciled_by`),
  CONSTRAINT `fk_payments_invoice` FOREIGN KEY (`invoice_id`) REFERENCES `invoices` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_payments_invoice_item` FOREIGN KEY (`invoice_item_id`) REFERENCES `invoice_items` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_payments_reconciled_by` FOREIGN KEY (`reconciled_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_payments_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_payments_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=454 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
